css:
.underwriter-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d6e2ec;
    background: radial-gradient(circle at 12% -10%, #122131 0%, #0b1622 45%, #070e17 100%);
    border-radius: 18px;
}

.underwriter-container * {
    box-sizing: border-box;
}

.underwriter-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0d2233 0%, #103a4f 55%, #0a5b53 100%);
    color: #eaf6f3;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(56, 224, 184, 0.18);
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.45);
}

.underwriter-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.underwriter-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #4fe3c1;
    background: rgba(79, 227, 193, 0.10);
    border: 1px solid rgba(79, 227, 193, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.underwriter-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 0.98rem;
    line-height: 1.55;
    color: #b6cdd8;
}

.underwriter-deal {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
}

.underwriter-deal-item {
    flex: 1;
    background: #0f1f2e;
    border: 1px solid #1c3346;
    border-left: 4px solid #2f7fb0;
    border-radius: 12px;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.underwriter-deal-item:nth-child(2) { border-left-color: #d9a23b; }
.underwriter-deal-item:nth-child(3) { border-left-color: #e0584f; }

.underwriter-deal-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 700;
    color: #7f99ac;
}

.underwriter-deal-value {
    font-size: 0.9rem;
    font-weight: 600;
    color: #e4eef5;
    line-height: 1.4;
}

.underwriter-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6c6;
    margin-bottom: 16px;
    padding: 2px 4px;
}

.underwriter-period-counter #currentDay,
.underwriter-period-counter #maxPeriods {
    font-weight: 800;
    color: #4fe3c1;
}

.underwriter-round-name {
    background: rgba(79, 227, 193, 0.12);
    color: #5fe7c9;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.8rem;
    font-weight: 700;
    margin-left: 4px;
}

.underwriter-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #f0b95a;
    background: rgba(217, 162, 59, 0.14);
    border: 1px solid rgba(217, 162, 59, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.underwriter-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.underwriter-status-card {
    background: linear-gradient(160deg, #102234 0%, #0c1a28 100%);
    border: 1px solid #1c3346;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border-top: 4px solid #2f7fb0;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.underwriter-card-ebitda { border-top-color: #4fe3c1; }
.underwriter-card-leverage { border-top-color: #d9a23b; }
.underwriter-card-raroc { border-top-color: #6aa9ff; }
.underwriter-card-portfolio { border-top-color: #b483e0; }

.underwriter-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa1b3;
}

.underwriter-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.underwriter-card-ebitda .underwriter-value { color: #4fe3c1; }
.underwriter-card-leverage .underwriter-value { color: #f0b95a; }
.underwriter-card-raroc .underwriter-value { color: #6aa9ff; }
.underwriter-card-portfolio .underwriter-value { color: #b483e0; }

.underwriter-sublabel {
    font-size: 0.74rem;
    color: #7f99ac;
    line-height: 1.35;
}

/* State-driven KPI colour stories. */
.underwriter-card-leverage.underwriter-lev-danger { border-top-color: #e0584f; }
.underwriter-card-leverage.underwriter-lev-danger .underwriter-value { color: #ff6f64; }
.underwriter-card-raroc.underwriter-raroc-good { border-top-color: #3fcf8e; }
.underwriter-card-raroc.underwriter-raroc-good .underwriter-value { color: #4ade9b; }
.underwriter-card-raroc.underwriter-raroc-bad { border-top-color: #e0584f; }
.underwriter-card-raroc.underwriter-raroc-bad .underwriter-value { color: #ff6f64; }
.underwriter-card-portfolio.underwriter-port-danger { border-top-color: #e0584f; }
.underwriter-card-portfolio.underwriter-port-danger .underwriter-value { color: #ff6f64; }

.underwriter-gauge-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f1f2e;
    border: 1px solid #1c3346;
    color: #9fb6c6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.underwriter-gauge-bar #ratingDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0b95a;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.underwriter-gauge-bar.underwriter-rating-good #ratingDisplay { color: #4ade9b; }
.underwriter-gauge-bar.underwriter-rating-bad #ratingDisplay { color: #ff6f64; }

.underwriter-briefing {
    display: flex;
    gap: 14px;
    background: #0f1f2e;
    border: 1px solid #1c3346;
    border-left: 5px solid #4fe3c1;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
}

.underwriter-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.underwriter-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf6f3;
    margin-bottom: 6px;
}

.underwriter-briefing-text {
    font-size: 0.94rem;
    line-height: 1.55;
    color: #c3d6e1;
}

.underwriter-briefing-text strong { color: #5fe7c9; }
.underwriter-briefing-text em { color: #f0b95a; font-style: italic; }

.underwriter-controls {
    background: #0f1f2e;
    border: 1px solid #1c3346;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
}

.underwriter-controls h3 {
    margin: 0 0 14px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #eaf6f3;
    border-bottom: 1px solid #1c3346;
    padding-bottom: 8px;
}

.underwriter-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.9rem;
    color: #c3d6e1;
    margin: 14px 0 6px;
}

.underwriter-container select,
.underwriter-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4257;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1521;
    color: #e4eef5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.underwriter-container select:focus,
.underwriter-container input[type="number"]:focus {
    outline: none;
    border-color: #4fe3c1;
    box-shadow: 0 0 0 3px rgba(79, 227, 193, 0.18);
}

.underwriter-container select option {
    background-color: #0a1521;
    color: #e4eef5;
}

.underwriter-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4fe3c1;
}

.underwriter-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6c6;
    margin-top: 6px;
}

.underwriter-range-readout #convictionReadout,
.underwriter-range-readout #marginReadout {
    color: #4fe3c1;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.underwriter-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.underwriter-container .btn-primary {
    background: linear-gradient(135deg, #0a5b53 0%, #4fe3c1 100%);
    border: none;
    color: #042019;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(79, 227, 193, 0.28);
}

.underwriter-container .btn-primary:hover {
    filter: brightness(1.08);
}

.underwriter-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2a4257;
    color: #9fb6c6;
    background: transparent;
}

.underwriter-coach {
    background: linear-gradient(160deg, #14110a 0%, #1f1709 100%);
    border: 1px solid rgba(240, 185, 90, 0.26);
    color: #f4e9d6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.38);
}

.underwriter-coach-header {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0b95a;
    margin-bottom: 8px;
}

.underwriter-coach-body {
    font-size: 0.94rem;
    line-height: 1.55;
    color: #ecdfca;
}

.underwriter-coach-body strong { color: #ffd27f; }
.underwriter-coach-body em { color: #ff9d7a; font-style: italic; }

.underwriter-history,
.underwriter-chart {
    background: #0f1f2e;
    border: 1px solid #1c3346;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
}

.underwriter-history h3,
.underwriter-chart h3 {
    margin: 0 0 14px;
    font-size: 1.06rem;
    font-weight: 800;
    color: #eaf6f3;
}

.underwriter-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.86rem;
    color: #c3d6e1;
}

.underwriter-container table#usfHistoryTable th {
    background: #0c1a28;
    color: #5fe7c9;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 1px solid #1c3346;
}

.underwriter-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #142536;
    color: #c3d6e1;
}

.underwriter-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0c1a28;
}

.underwriter-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .underwriter-container {
        padding: 14px;
    }
    .underwriter-header h1 {
        font-size: 1.7rem;
    }
    .underwriter-deal {
        flex-direction: column;
    }
    .underwriter-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .underwriter-value {
        font-size: 2rem;
    }
    .underwriter-clock {
        margin-left: 0;
    }
    .underwriter-period-counter {
        font-size: 0.88rem;
    }
    .underwriter-gauge-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .underwriter-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / credit-committee debrief screen (underwriter) ---- */
.underwriter-cm { padding: 8px 4px 4px; color: #e3e9ef; }
.underwriter-cm-head { text-align: center; margin-bottom: 18px; }
.underwriter-cm-score { font-size: 3.4rem; font-weight: 800; line-height: 1; color: #d4a24c; }
.underwriter-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #9aa7b4; }
.underwriter-cm-verdict { font-size: 1.15rem; font-weight: 700; margin-top: 8px; color: #eef3f8; }
.underwriter-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.76rem; font-weight: 700; vertical-align: middle; }
.underwriter-cm-yes { background: rgba(212,162,76,0.16); color: #d4a24c; border: 1px solid rgba(212,162,76,0.5); }
.underwriter-cm-no { background: rgba(190,80,70,0.13); color: #d38a7c; border: 1px solid rgba(190,80,70,0.45); }
.underwriter-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 14px 0; }
.underwriter-cm-metric { flex: 1 1 110px; min-width: 96px; background: rgba(212,162,76,0.07); border: 1px solid rgba(212,162,76,0.22); border-radius: 10px; padding: 12px 8px; text-align: center; }
.underwriter-cm-mv { display: block; font-size: 1.5rem; font-weight: 800; color: #d4a24c; }
.underwriter-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #9aa7b4; text-transform: uppercase; letter-spacing: 0.04em; }
.underwriter-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin: 4px 0 16px; }
.underwriter-cm-chip { font-size: 0.78rem; font-weight: 600; padding: 4px 12px; border-radius: 999px; border: 1px solid transparent; }
.underwriter-cm-chip-on { background: rgba(212,162,76,0.14); color: #e6bd72; border-color: rgba(212,162,76,0.4); }
.underwriter-cm-chip-off { background: rgba(154,167,180,0.08); color: #8494a2; border-color: rgba(154,167,180,0.22); }
.underwriter-cm-debrief-title { font-weight: 700; margin: 10px 0 6px; color: #eef3f8; }
.underwriter-cm-insights { margin: 0; padding-left: 20px; }
.underwriter-cm-insights li { margin-bottom: 9px; line-height: 1.55; font-size: 0.92rem; color: #cbd6e0; }

