(function() {
    'use strict';

    class RiskUnderwriterAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Risk Underwriter`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Banco Atlântico Norte / Cerâmica Duramax). ----
            this.REPORTED_EBITDA = 14.2;     // € M audited
            this.ADJUSTED_EBITDA = 17.5;     // € M sponsor "adjusted"
            this.PARTIAL_EBITDA = 15.9;      // € M split-the-difference
            this.ADDBACKS = 3.3;             // € M disputed add-backs
            this.LOAN = 45;                  // € M senior term loan
            this.PORT_LIMIT = 1200;          // € M leveraged-finance internal limit
            this.PORT_DRAWN = 1008;          // € M drawn pre-deal (84% of 1200)
            this.HURDLE = 12.0;              // % desk RAROC hurdle
            this.SPONSOR_MARGIN = 350;       // bps over Euribor
            this.MODEL_MARGIN = 475;         // bps over Euribor (model-implied)
            this.LGD = 0.45;                 // loss-given-default (senior, partly secured)
            this.CAPITAL_RATIO = 0.20;       // economic capital as % of exposure (high-yield LBO senior)

            // ---- Concept truths (the modelled best play). ----
            this.TRUE_EBITDA_CHOICE = `reject_all`;
            this.TRUE_RATING = `b`;
            this.TRUE_DRIVER = `leverage`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    underwritingEBITDA: this.ADJUSTED_EBITDA,   // starts on the sponsor's number until R1 decides
                    leverage: Math.round((this.LOAN / this.ADJUSTED_EBITDA) * 10) / 10, // 2.6x on adjusted
                    quality: 35,                 // financial-information-quality score (0-100)
                    pd: 4.0,                     // probability of default (%)
                    raroc: 0,                    // risk-adjusted return on capital (%)
                    covenantStrength: 0,         // covenant package strength (0-100)
                    portfolioUtil: 84,           // leveraged-finance book utilisation (%)
                    rating: `B`,                 // internal rating label
                    // ---- Sticky run-defining penalty flags. ----
                    flagAdjEBITDA: false,        // underwrote to sponsor's add-backs
                    flagNoStress: false,         // skipped the cyclical stress
                    flagUnderpriced: false,      // priced at/below the sponsor's ask
                    flagWeakCovenant: false,     // covenant-lite / no maintenance test
                    flagOverConcentrated: false, // took the full ticket over the limit
                    flagBinaryDecline: false,    // walked without structuring
                    leverageHistory: [Math.round((this.LOAN / this.ADJUSTED_EBITDA) * 10) / 10],
                    rarocHistory: [0],
                    covenantHistory: [0],
                    qualityHistory: [35],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    addbacks: `accept_all`,
                    receivables: `ignore`,
                    scorecard: `green`,
                    conviction: 40,
                    rating: `bb`,
                    stress: `skip`,
                    driver: `margin`,
                    margin: 350,
                    fees: `0.5`,
                    covenant: `none`,
                    structure: `none`,
                    decision: `approve_full`,
                    committee: `relationship`,
                    appetite: `win`,
                    hold: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ab = document.getElementById(`addbacksInput`);
                const re = document.getElementById(`receivablesInput`);
                const sc = document.getElementById(`scorecardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ab) decisions.addbacks = ab.value;
                if (re) decisions.receivables = re.value;
                if (sc) decisions.scorecard = sc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 2) {
                const ra = document.getElementById(`ratingInput`);
                const st = document.getElementById(`stressInput`);
                const dr = document.getElementById(`driverInput`);
                if (ra) decisions.rating = ra.value;
                if (st) decisions.stress = st.value;
                if (dr) decisions.driver = dr.value;
            } else if (round === 3) {
                const mg = document.getElementById(`marginInput`);
                const fe = document.getElementById(`feesInput`);
                const co = document.getElementById(`covenantInput`);
                const sr = document.getElementById(`structureInput`);
                if (mg) decisions.margin = parseInt(mg.value, 10);
                if (fe) decisions.fees = fe.value;
                if (co) decisions.covenant = co.value;
                if (sr) decisions.structure = sr.value;
                if (!Number.isFinite(decisions.margin) || decisions.margin < 200 || decisions.margin > 700) {
                    warn(`warn_margin_range`); return false;
                }
            } else if (round === 4) {
                const de = document.getElementById(`decisionInput`);
                const cm = document.getElementById(`committeeInput`);
                const ap = document.getElementById(`appetiteInput`);
                const ho = document.getElementById(`holdInput`);
                if (de) decisions.decision = de.value;
                if (cm) decisions.committee = cm.value;
                if (ap) decisions.appetite = ap.value;
                if (ho) decisions.hold = parseInt(ho.value, 10);
                if (!Number.isFinite(decisions.hold) || decisions.hold < 0 || decisions.hold > 100) {
                    warn(`warn_hold_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        // ---- Expected loss & RAROC engine (used in R3 and the final summary). ----
        _computeRaroc(marginBps, feesPct, ds, exposureM) {
            const pd = ds.pd / 100;                          // probability of default
            const lgd = this.LGD;                            // loss-given-default
            const margin = marginBps / 10000;               // bps -> fraction
            const feeAmortised = (feesPct / 100) / 5;        // one-off fees spread over 5-year tenor
            const expectedLoss = pd * lgd;                   // EL rate on exposure
            const capital = exposureM * this.CAPITAL_RATIO;  // economic capital held against a B / 3.2x credit
            const revenue = exposureM * (margin + feeAmortised);
            const lossCharge = exposureM * expectedLoss;     // expected loss = PD x LGD x exposure
            const opCost = exposureM * 0.004;                // servicing / origination cost
            const netReturn = revenue - lossCharge - opCost; // return on the capital at risk
            if (capital <= 0) return 0;
            return Math.round((netReturn / capital) * 1000) / 10; // % to one decimal
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Read the borrower: convert reported earnings into underwriting EBITDA. ----
                switch (d.addbacks) {
                    case `reject_all`:
                        ds.underwritingEBITDA = this.REPORTED_EBITDA;
                        ds.flagAdjEBITDA = false;
                        ds.quality += 30;
                        coachKey = `coach_r1_reject`;
                        break;
                    case `accept_partial`:
                        ds.underwritingEBITDA = this.PARTIAL_EBITDA;
                        ds.flagAdjEBITDA = true;          // still lending against unsigned add-backs
                        ds.quality += 6;
                        coachKey = `coach_r1_partial`;
                        break;
                    case `accept_all`:
                        ds.underwritingEBITDA = this.ADJUSTED_EBITDA;
                        ds.flagAdjEBITDA = true;
                        ds.quality -= 6;
                        coachKey = `coach_r1_accept`;
                        break;
                }

                switch (d.receivables) {
                    case `haircut`: ds.quality += 14; break;
                    case `note`: ds.quality += 6; break;
                    case `ignore`: ds.quality -= 8; if (coachKey === `coach_r1_reject`) coachKey = `coach_r1_receivables`; break;
                }

                switch (d.scorecard) {
                    case `forensic`: ds.quality += 16; break;
                    case `mixed`: ds.quality += 4; break;
                    case `green`: ds.quality -= 10; if (coachKey === `coach_r1_reject`) coachKey = `coach_r1_greenflag`; break;
                }

                // Conviction to hold the number reinforces a defensible read.
                if (d.conviction >= 60) ds.quality += 6;
                else if (d.conviction <= 25) ds.quality -= 4;

                ds.leverage = Math.round((this.LOAN / ds.underwritingEBITDA) * 10) / 10;

                summaryKey = (d.addbacks === `reject_all` && d.receivables === `haircut` && d.scorecard === `forensic`)
                    ? `sum_r1_good`
                    : (d.addbacks === `reject_all` ? `sum_r1_partial` : `sum_r1_weak`);
            } else if (round === 2) {
                // ---- Score the default risk off the chosen EBITDA. ----
                // The defensible rating depends on the leverage the team actually carries.
                const trueLeverage = this.LOAN / ds.underwritingEBITDA;
                let basePd;
                if (trueLeverage >= 3.1) basePd = 4.5;       // 3.2x on stripped earnings -> B
                else if (trueLeverage >= 2.8) basePd = 3.0;
                else basePd = 1.8;                            // 2.6x on inflated earnings (looks safe, isn't)

                // Rating choice: rewarded for matching the true leverage picture.
                switch (d.rating) {
                    case `b`:
                        ds.rating = `B`;
                        if (trueLeverage >= 3.1) { ds.quality += 8; coachKey = `coach_r2_ratingright`; }
                        break;
                    case `bminus`:
                        ds.rating = `B−`;
                        basePd += 2.5;                        // conservative; defensible if leverage is high
                        if (trueLeverage >= 3.1) ds.quality += 4;
                        break;
                    case `bb`:
                        ds.rating = `BB`;
                        basePd = Math.min(basePd, 1.8);       // optimistic — the sponsor's rating
                        if (trueLeverage >= 3.1) { coachKey = `coach_r2_ratingsoft`; }
                        break;
                }

                // Cyclical stress test (a 25-30% EBITDA decline).
                switch (d.stress) {
                    case `full`:
                        ds.quality += 12;
                        if (coachKey === `coach_default` || coachKey === `coach_r2_ratingright`) coachKey = `coach_r2_stressfull`;
                        break;
                    case `mild`:
                        basePd += 1.0;                        // under-modelled downturn understates PD
                        break;
                    case `skip`:
                        ds.flagNoStress = true;
                        basePd += 2.0;                        // unmodelled cyclicality is uncompensated risk
                        ds.quality -= 8;
                        coachKey = `coach_r2_nostress`;
                        break;
                }

                // The single risk driver.
                switch (d.driver) {
                    case `leverage`: ds.quality += 8; if (coachKey === `coach_default`) coachKey = `coach_r2_driverright`; break;
                    case `margin`: ds.quality -= 4; coachKey = `coach_r2_drivermargin`; break;
                    case `sponsor`: ds.quality -= 4; coachKey = `coach_r2_driversponsor`; break;
                }

                ds.pd = Math.max(1.0, Math.round(basePd * 10) / 10);

                summaryKey = (d.stress === `full` && d.driver === `leverage`)
                    ? ((d.rating === `b` || d.rating === `bminus`) ? `sum_r2_good` : `sum_r2_softrating`)
                    : (d.stress === `skip` ? `sum_r2_nostress` : `sum_r2_weak`);
            } else if (round === 3) {
                // ---- Price the loan and set the covenant. ----
                const feesPct = parseFloat(d.fees);

                if (d.margin <= 375) {
                    ds.flagUnderpriced = true;                // priced at/around the sponsor's ask
                    coachKey = `coach_r3_underprice`;
                } else if (d.margin >= 450) {
                    coachKey = `coach_r3_priceright`;
                }

                // Covenant package strength.
                switch (d.covenant) {
                    case `package`: ds.covenantStrength = 70; ds.flagWeakCovenant = false; break;
                    case `single`: ds.covenantStrength = 42; ds.flagWeakCovenant = false; break;
                    case `none`: ds.covenantStrength = 14; ds.flagWeakCovenant = true; coachKey = `coach_r3_covlite`; break;
                }

                // Structural protection lowers LGD-driven risk and lifts covenant strength.
                switch (d.structure) {
                    case `cushion`: ds.covenantStrength = Math.min(100, ds.covenantStrength + 26); ds.quality += 6; break;
                    case `amort`: ds.covenantStrength = Math.min(100, ds.covenantStrength + 12); break;
                    case `none`: ds.covenantStrength = Math.max(0, ds.covenantStrength - 6); if (coachKey === `coach_default`) coachKey = `coach_r3_nostructure`; break;
                }

                // Good covenants & cushion buy a small PD improvement (early warning + lower loss).
                if (ds.covenantStrength >= 80) ds.pd = Math.max(1.0, Math.round((ds.pd - 0.6) * 10) / 10);

                // Compute RAROC on the full €45M hold at this price.
                ds.raroc = this._computeRaroc(d.margin, feesPct, ds, this.LOAN);

                if (!ds.flagWeakCovenant && !ds.flagUnderpriced && ds.raroc >= this.HURDLE && d.structure === `cushion`) {
                    coachKey = `coach_r3_structured`;
                }

                summaryKey = (!ds.flagUnderpriced && !ds.flagWeakCovenant && ds.raroc >= this.HURDLE)
                    ? `sum_r3_good`
                    : (ds.flagUnderpriced ? `sum_r3_underpriced` : (ds.flagWeakCovenant ? `sum_r3_covlite` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Portfolio decision and the credit-committee pitch. ----
                const feesPct = parseFloat(d.fees);

                switch (d.decision) {
                    case `approve_full`:
                        ds.portfolioUtil = Math.round((this.PORT_DRAWN + this.LOAN) / this.PORT_LIMIT * 100); // ~88%
                        ds.flagOverConcentrated = true;
                        ds.raroc = this._computeRaroc(d.margin, feesPct, ds, this.LOAN);
                        coachKey = `coach_r4_full`;
                        break;
                    case `decline`:
                        ds.portfolioUtil = 84;                 // book unchanged
                        ds.flagBinaryDecline = true;
                        ds.raroc = 0;                          // no deal, no return — relationship lost
                        coachKey = `coach_r4_decline`;
                        break;
                    case `conditions`:
                        ds.portfolioUtil = Math.round((this.PORT_DRAWN + this.LOAN) / this.PORT_LIMIT * 100); // ~88%
                        ds.raroc = this._computeRaroc(d.margin, feesPct, ds, this.LOAN);
                        coachKey = `coach_r4_conditions`;
                        break;
                    case `reduced_hold`:
                        // Keep €25M, syndicate €20M — frees capacity, holds inside the limit.
                        ds.portfolioUtil = Math.round((this.PORT_DRAWN + 25) / this.PORT_LIMIT * 100); // ~86%
                        ds.raroc = this._computeRaroc(d.margin, feesPct, ds, 25);
                        ds.flagOverConcentrated = false;
                        coachKey = `coach_r4_reducedhold`;
                        break;
                }

                // Decision coaches that carry their own teaching point and should
                // not be silently overwritten by every committee pitch.
                const goodDecisionCoach = (coachKey === `coach_r4_conditions` || coachKey === `coach_r4_reducedhold`);

                // The committee pitch — what you lead with. A wrong pitch (margin /
                // relationship) is the dominant error and overrides the decision coach;
                // the right pitch (RAROC) rewards a structured decision with pitchright,
                // but on a structured decision a clean closing (priced appetite) lets the
                // decision's own coaching stand.
                switch (d.committee) {
                    case `raroc`:
                        ds.quality += 8;
                        if (goodDecisionCoach && d.appetite !== `priced`) coachKey = `coach_r4_pitchright`;
                        break;
                    case `margin`: ds.quality -= 6; coachKey = `coach_r4_pitchmargin`; break;
                    case `relationship`: ds.quality -= 8; coachKey = `coach_r4_pitchrel`; break;
                }

                // Risk-appetite framing. A weak appetite surfaces its own coaching when
                // the decision itself did not already raise a structuring error.
                const decisionCoach = (coachKey === `coach_r4_full` || coachKey === `coach_r4_decline` || coachKey === `coach_r4_conditions` || coachKey === `coach_r4_reducedhold`);
                switch (d.appetite) {
                    case `priced`: ds.quality += 6; break;
                    case `win`: ds.quality -= 6; if (decisionCoach || coachKey === `coach_default`) coachKey = `coach_r4_appetitewin`; break;
                    case `avoid`: ds.quality -= 4; if (decisionCoach || coachKey === `coach_default`) coachKey = `coach_r4_appetiteavoid`; break;
                }

                // Holding the line under pressure protects price & covenant integrity.
                if (d.hold >= 60) ds.quality += 4;
                else if (d.hold <= 25 && !ds.flagUnderpriced) { ds.quality -= 4; ds.flagUnderpriced = true; }

                summaryKey = ((d.decision === `conditions` || d.decision === `reduced_hold`) && d.committee === `raroc`)
                    ? `sum_r4_good`
                    : (d.decision === `decline` ? `sum_r4_decline` : (d.decision === `approve_full` ? `sum_r4_full` : `sum_r4_weak`));
            }

            // ---- Clamp the running KPIs. ----
            ds.quality = Math.max(0, Math.min(100, Math.round(ds.quality)));
            ds.leverage = Math.round((this.LOAN / ds.underwritingEBITDA) * 10) / 10;
            ds.pd = Math.max(1.0, Math.round(ds.pd * 10) / 10);
            ds.covenantStrength = Math.max(0, Math.min(100, Math.round(ds.covenantStrength)));
            ds.portfolioUtil = Math.max(0, Math.min(120, Math.round(ds.portfolioUtil)));
            ds.raroc = Math.round(ds.raroc * 10) / 10;

            // Internal-rating label tracks PD.
            if (ds.pd <= 2.0) ds.rating = `BB`;
            else if (ds.pd <= 5.0) ds.rating = `B`;
            else ds.rating = `B− / CCC+`;

            ds.leverageHistory.push(ds.leverage);
            ds.rarocHistory.push(ds.raroc);
            ds.covenantHistory.push(ds.covenantStrength);
            ds.qualityHistory.push(ds.quality);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Persist composite (0-100) where express_extractMetrics reads it every period.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                underwritingEBITDA: ds.underwritingEBITDA,
                leverage: ds.leverage,
                quality: ds.quality,
                pd: ds.pd,
                rating: ds.rating,
                raroc: ds.raroc,
                covenantStrength: ds.covenantStrength,
                portfolioUtil: ds.portfolioUtil,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: ds.performance.overallScore,
                score: ds.performance.overallScore
            };
        }

        _fmtEbitda(v) {
            return `€` + (Math.round(Number(v) * 10) / 10).toFixed(1).replace(/\.0$/, ``) + `M`;
        }

        _fmtLeverage(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return s + `×`;
        }

        _fmtRaroc(v) {
            const n = Number(v);
            if (!n) return `—`;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = (Math.round(n * 10) / 10).toFixed(1);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return s + `%`;
        }

        _ratingLabel(ds) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let pd = (Math.round(ds.pd * 10) / 10).toFixed(1);
            if (lang === `es`) pd = pd.replace(`.`, `,`);
            return ds.rating + ` · ` + t(`rating_pd`) + ` ~` + pd + `%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`ebitdaDisplay`, `domainState.underwritingEBITDA`, (v) => self._fmtEbitda(v));

            uiManager.bind(`leverageDisplay`, `domainState.leverage`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.underwriter-card-leverage`);
                if (card) card.classList.toggle(`underwriter-lev-danger`, n >= 3.1);
                return self._fmtLeverage(n);
            });

            uiManager.bind(`rarocDisplay`, `domainState.raroc`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.underwriter-card-raroc`);
                if (card) {
                    card.classList.toggle(`underwriter-raroc-good`, n >= self.HURDLE);
                    card.classList.toggle(`underwriter-raroc-bad`, n > 0 && n < self.HURDLE);
                }
                return self._fmtRaroc(n);
            });

            uiManager.bind(`portfolioDisplay`, `domainState.portfolioUtil`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.underwriter-card-portfolio`);
                if (card) card.classList.toggle(`underwriter-port-danger`, n >= 88);
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`ratingDisplay`, `domainState.pd`, () => {
                const ds = window.mySimulation.state.domainState;
                const bar = document.querySelector(`.underwriter-gauge-bar`);
                if (bar) {
                    bar.classList.toggle(`underwriter-rating-good`, ds.pd <= 2.0 && !ds.flagAdjEBITDA === false ? false : ds.pd <= 2.5 && ds.covenantStrength >= 60);
                    bar.classList.toggle(`underwriter-rating-bad`, ds.pd >= 6.0);
                }
                return self._ratingLabel(ds);
            });

            // Conviction slider readout.
            const cv = document.getElementById(`convictionInput`);
            const cvReadout = document.getElementById(`convictionReadout`);
            if (cv && cvReadout) {
                cvReadout.textContent = cv.value;
                cv.addEventListener(`input`, function() { cvReadout.textContent = cv.value; });
            }

            // Margin readout.
            const mg = document.getElementById(`marginInput`);
            const mgReadout = document.getElementById(`marginReadout`);
            if (mg && mgReadout) {
                mgReadout.textContent = mg.value;
                mg.addEventListener(`input`, function() { mgReadout.textContent = mg.value; });
            }
        }

        getChartConfig() {
            return {
                creditRiskChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_leverage`, `True leverage (×, scaled ×20)`),
                                data: [],
                                borderColor: `#f0b95a`,
                                backgroundColor: `rgba(240,185,90,0.10)`,
                                borderWidth: 3,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#f0b95a`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_raroc`, `RAROC (%)`),
                                data: [],
                                borderColor: `#6aa9ff`,
                                backgroundColor: `rgba(106,169,255,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#6aa9ff`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_covenant`, `Covenant strength (0–100, ÷5)`),
                                data: [],
                                borderColor: `#4fe3c1`,
                                backgroundColor: `rgba(79,227,193,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4fe3c1`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb6c6`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                position: `left`,
                                ticks: { color: `#7f99ac` },
                                grid: { color: `rgba(159,182,198,0.10)` },
                                title: { display: true, text: this._cl(`axis_scale`, `Indexed (≈%)`), color: `#7f99ac` }
                            },
                            x: {
                                ticks: { color: `#7f99ac` },
                                grid: { color: `rgba(159,182,198,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#7f99ac` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.rarocHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Put three different scales on one 0–100 axis: leverage ×20, RAROC as-is, covenant ÷5.
            const levScaled = ds.leverageHistory.map((v) => Math.round(v * 20));
            const covScaled = ds.covenantHistory.map((v) => Math.round(v / 5));
            return {
                creditRiskChart: {
                    labels: labels,
                    datasets: [
                        { data: levScaled },
                        { data: ds.rarocHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: covScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            const raroc = Math.round(ds.raroc * 10) / 10;
            const covenant = Math.round(ds.covenantStrength);
            const quality = Math.round(ds.quality);
            const cleanEarnings = !ds.flagAdjEBITDA;
            const rarocScore = Math.max(0, Math.min(100, (raroc / this.HURDLE) * 60));
            return Math.round(quality * 0.30 + rarocScore * 0.30 + covenant * 0.25 + (cleanEarnings ? 15 : 0));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        _gradeLabel(perf) {
            const map = {
                "Value Destroyed": `grade_destroyed`,
                "Credit Approved — Risk-Adjusted": `grade_approved`,
                "Underwrote the Seller's Number": `grade_sellernum`,
                "Priced to Win, Below Hurdle": `grade_underpriced`,
                "Blind Without Covenants": `grade_covlite`,
                "Over-Concentrated the Book": `grade_concentration`,
                "Walked From a Structurable Deal": `grade_walked`,
                "Sound Credit, Loose Ends": `grade_looseends`,
            };
            const key = map[perf];
            return key ? this._cl(key, perf) : perf;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;

            const ebitda = Math.round(ds.underwritingEBITDA * 10) / 10;
            const leverage = Math.round(ds.leverage * 10) / 10;
            const raroc = Math.round(ds.raroc * 10) / 10;
            const covenant = Math.round(ds.covenantStrength);
            const quality = Math.round(ds.quality);
            const portfolio = Math.round(ds.portfolioUtil);

            // ---- Gates for the top verdict. ----
            const cleanEarnings = !ds.flagAdjEBITDA;                  // underwrote to the audited base
            const pricedToHurdle = !ds.flagUnderpriced && raroc >= this.HURDLE;
            const strongCovenant = !ds.flagWeakCovenant && covenant >= 70;
            const fitsPortfolio = !ds.flagOverConcentrated;
            const structured = !ds.flagBinaryDecline;

            // Composite score (out of 100) — only meaningful alongside the gates.
            const rarocScore = Math.max(0, Math.min(100, (raroc / this.HURDLE) * 60));
            const composite = Math.round(
                quality * 0.30 + rarocScore * 0.30 + covenant * 0.25 + (cleanEarnings ? 15 : 0)
            );

            // ---- Verdict ladder (sticky flags GATE the top outcomes). ----
            let performance = `Value Destroyed`;
            if (cleanEarnings && pricedToHurdle && strongCovenant && fitsPortfolio && structured && composite >= 78) {
                performance = `Credit Approved — Risk-Adjusted`;
            } else if (ds.flagAdjEBITDA) {
                performance = `Underwrote the Seller's Number`;
            } else if (ds.flagUnderpriced) {
                performance = `Priced to Win, Below Hurdle`;
            } else if (ds.flagWeakCovenant) {
                performance = `Blind Without Covenants`;
            } else if (ds.flagOverConcentrated) {
                performance = `Over-Concentrated the Book`;
            } else if (ds.flagBinaryDecline) {
                performance = `Walked From a Structurable Deal`;
            } else if (cleanEarnings && pricedToHurdle && composite >= 60) {
                performance = `Sound Credit, Loose Ends`;
            }

            const insights = [];
            if (performance === `Credit Approved — Risk-Adjusted`) insights.push(window.mySimulation.t(`insight_approved`));
            if (ds.flagAdjEBITDA) insights.push(window.mySimulation.t(`insight_adjebitda`));
            if (ds.flagUnderpriced) insights.push(window.mySimulation.t(`insight_underpriced`));
            if (ds.flagWeakCovenant) insights.push(window.mySimulation.t(`insight_covlite`));
            if (ds.flagOverConcentrated) insights.push(window.mySimulation.t(`insight_concentration`));
            if (ds.flagBinaryDecline) insights.push(window.mySimulation.t(`insight_decline`));
            if (ds.flagNoStress) insights.push(window.mySimulation.t(`insight_nostress`));
            if (cleanEarnings && leverage >= 3.1) insights.push(window.mySimulation.t(`insight_trueleverage`));
            if (performance === `Sound Credit, Loose Ends`) insights.push(window.mySimulation.t(`insight_looseends`));
            if (!insights.length) insights.push(window.mySimulation.t(`insight_looseends`));

            return {
                ebitda: ebitda,
                leverage: leverage,
                raroc: raroc,
                covenant: covenant,
                quality: quality,
                portfolio: portfolio,
                cleanEarnings: cleanEarnings,
                pricedToHurdle: pricedToHurdle,
                strongCovenant: strongCovenant,
                fitsPortfolio: fitsPortfolio,
                structured: structured,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                met: (cleanEarnings && pricedToHurdle && strongCovenant && fitsPortfolio && structured && composite >= 78),
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function (k) { return window.mySimulation.t(k); }
                : function (k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const verdict = s.performanceLabel || s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="underwriter-cm-badge underwriter-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="underwriter-cm-badge underwriter-cm-no">` + T(`cm_notmet`) + `</span>`;
            const chip = function (ok, key) {
                return `<span class="underwriter-cm-chip ` + (ok ? `underwriter-cm-chip-on` : `underwriter-cm-chip-off`) + `">`
                    + (ok ? `✓ ` : `· `) + T(key) + `</span>`;
            };
            const chips = chip(!!s.cleanEarnings, `cm_b_clean`) + chip(!!s.pricedToHurdle, `cm_b_hurdle`)
                + chip(!!s.strongCovenant, `cm_b_covenant`) + chip(!!s.fitsPortfolio, `cm_b_portfolio`);
            const md = function (val, key) {
                return `<div class="underwriter-cm-metric"><span class="underwriter-cm-mv">` + val
                    + `</span><span class="underwriter-cm-ml">` + T(key) + `</span></div>`;
            };
            const metrics = md((Math.round((s.leverage || 0) * 10) / 10) + `×`, `cm_m_leverage`)
                + md((Math.round((s.raroc || 0) * 10) / 10) + `%`, `cm_m_raroc`)
                + md(Math.round(s.covenant || 0), `cm_m_covenant`)
                + md(Math.round(s.quality || 0), `cm_m_quality`);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function (t) { return `<li>` + t + `</li>`; }).join(``);
            return `<div class="underwriter-cm">`
                + `<div class="underwriter-cm-head">`
                +   `<div class="underwriter-cm-score">` + score + `<span class="underwriter-cm-score-max">/100</span></div>`
                +   `<div class="underwriter-cm-verdict">` + verdict + ` ` + badge + `</div>`
                + `</div>`
                + `<div class="underwriter-cm-metrics">` + metrics + `</div>`
                + `<div class="underwriter-cm-chips">` + chips + `</div>`
                + `<div class="underwriter-cm-debrief-title">` + T(`cm_debrief`) + `</div>`
                + `<ul class="underwriter-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.flagAdjEBITDA) return window.mySimulation.t(`hint_adjebitda`);
            if (ds.flagWeakCovenant && state.currentPeriod >= 3) return window.mySimulation.t(`hint_covenant`);
            if (ds.flagUnderpriced && state.currentPeriod >= 3) return window.mySimulation.t(`hint_underpriced`);
            if (ds.flagOverConcentrated) return window.mySimulation.t(`hint_concentration`);
            if (ds.flagNoStress && state.currentPeriod >= 2) return window.mySimulation.t(`hint_stress`);
            if (!ds.flagAdjEBITDA && ds.raroc >= this.HURDLE && ds.covenantStrength >= 70) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.leverage`, label: `Leverage`, i18nKey: `col_leverage`, formatter: (v) => self._fmtLeverage(Number(v)) },
                { key: `results.raroc`, label: `RAROC`, i18nKey: `col_raroc`, formatter: (v) => self._fmtRaroc(Number(v)) },
                { key: `results.covenantStrength`, label: `Covenant`, i18nKey: `col_covenant`, formatter: (v) => `${Math.round(Number(v))}` },
                { key: `results.portfolioUtil`, label: `Portfolio`, i18nKey: `col_portfolio`, formatter: (v) => `${Math.round(Number(v))}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

